    val GENOME_KT_BROKEN: String = "package com.androidharness.app.evolve\n\nimport java.security.MessageDigest\nimport kotlinx.serialization.Serializable\nimport kotlinx.serialization.json.Json\n\n/**\n * A command hook the harness runs, kept in the genome rather than a plugin file so a\n * candidate can add or remove one without touching the APK. Only events this app\n * already fires are allowed; [GenomeRules] refuses anything else.\n */\n@Serializable\ndata class GenomeHook(\n    val event: String,\n    val matcher: String = \"\",\n    val command: String,\n    val timeout: Int = 60,\n)\n\n/** A named agent profile in the genome: instructions, a preferred model and the tools it may see. */\n@Serializable\ndata class GenomeAgent(\n    val name: String,\n    val instructions: String = \"\",\n    val model: String? = null,\n    val tools: List<String> = emptyList(),\n)\n\n/**\n * The harness genome: the part of the agent that is allowed to learn. Model weights\n * never appear here, and neither do permissions, the evaluator or the safety probes.\n *\n * The content id is the sha256 of the canonical payload, cut to 16 hex characters, so\n * two genomes that mean the same thing always get the same id and the archive can\n * refuse a candidate it has already seen. [parent], [createdAt], [label], [hypothesis]\n * and [id] are lineage and presentation, not genome content, so they stay out of the\n * payload and changing them does not mint a new genome.\n */\n@Serializable\ndata class Genome(\n    val id: String = \"\",\n    val parent: String? = null,\n    val createdAt: Long = 0L,\n    val label: String = \"\",\n    val hypothesis: String = \"\",\n    val instructions: List<String> = emptyList(),\n    /** Skill name to full SKILL.md text. */\n    val skills: Map<String, String> = emptyMap(),\n    val skillEnable: Set<String> = emptySet(),\n    val hooks: List<GenomeHook> = emptyList(),\n    val agents: Map<String, GenomeAgent> = emptyMap(),\n    /** The proposer's own working notes, so the next generation can read why the last patch was tried. */\n    val proposerNotes: String = \"\",\n) {\n    /** Everything a genome may evolve, normalized so equal content serializes byte for byte. */\n    fun payload(): Genome = copy(\n        id = \"\",\n        parent = null,\n        createdAt = 0L,\n        label = \"\",\n        hypothesis = \"\",\n        instructions = instructions.map { it.trim() }.filter { it.isNotEmpty() },\n        skills = skills.mapValues { (_, text) -> text.replace(\"\\r\\n\", \"\\n\").trimEnd() }.toSortedMap(),\n        skillEnable = skillEnable.toSortedSet(),\n        hooks = hooks.sortedWith(compareBy({ it.event }, { it.matcher }, { it.command }, { it.timeout })),\n        agents = agents.toSortedMap(),\n        proposerNotes = proposerNotes.replace(\"\\r\\n\", \"\\n\").trim(),\n    )\n\n    fun canonical(): String = CANONICAL.encodeToString(serializer(), payload())\n\n    fun computeId(): String = sha256(canonical()).take(ID_LENGTH)\n\n    /** A copy carrying the id its content earns. */\n    fun identified(): Genome = copy(id = computeId())\n\n    /** A short, readable account of every field that differs, for the diff tool and cards. */\n    fun diff(other: Genome): String {\n        val out = mutableListOf<String>()\n        if (instructions != other.instructions) out += listDiff(\"instructions\", instructions, other.instructions)\n        (skills.keys + other.skills.keys).sorted().forEach { name ->\n            val before = skills[name]\n            val after = other.skills[name]\n            if (before != after) out += when {\n                before == null -> \"skill \$name: added\"\n                after == null -> \"skill \$name: removed\"\n                else -> \"skill \$name: changed (\${before.length} -> \${after.length} chars)\"\n            }\n        }\n        if (skillEnable != other.skillEnable) {\n            out += \"enabled skills: +\${(other.skillEnable - skillEnable).size} -\${(skillEnable - other.skillEnable).size}\"\n        }\n        if (hooks != other.hooks) {\n            out += listDiff(\"hooks\", hooks.map(::describeHook), other.hooks.map(::describeHook))\n        }\n        (agents.keys + other.agents.keys).sorted().forEach { name ->\n            val before = agents[name]\n            val after = other.agents[name]\n            if (before != after) out += when {\n                before == null -> \"agent \$name: added\"\n                after == null -> \"agent \$name: removed\"\n                else -> \"agent \$name: changed\"\n            }\n        }\n        if (proposerNotes != other.proposerNotes) out += \"proposer notes: changed\"\n        return if (out.isEmpty()) \"No content changes.\" else out.joinToString(\"\\n\")\n    }\n\n    companion object {\n        // BUG INTRODUCED FOR THIS TASK: the id must be 16 hex characters, not 15.\n        private const val ID_LENGTH = 15\n        const val MAX_LABEL = 80\n        const val MAX_HYPOTHESIS = 500\n\n        val CANONICAL = Json { encodeDefaults = true; explicitNulls = false }\n\n        fun sha256(text: String): String =\n            MessageDigest.getInstance(\"SHA-256\").digest(text.toByteArray(Charsets.UTF_8))\n                .joinToString(\"\") { \"%02x\".format(it) }\n\n        /** The starting point: no instructions of its own, no skills, no hooks. */\n        fun baseline(now: Long = System.currentTimeMillis()): Genome =\n            Genome(createdAt = now, label = \"Baseline\", hypothesis = \"The harness as it shipped.\").identified()\n\n        private fun describeHook(hook: GenomeHook): String =\n            \"\${hook.event}\${if (hook.matcher.isBlank()) \"\" else \" (\${hook.matcher})\"}: \${hook.command}\"\n\n        private fun listDiff(name: String, before: List<String>, after: List<String>): String = buildString {\n            append(name).append(\": +\").append(after.size).append(\" -\").append(before.size)\n            (before - after.toSet()).forEach { append(\"\\n  - \").append(it.lineSequence().first().take(160)) }\n            (after - before.toSet()).forEach { append(\"\\n  + \").append(it.lineSequence().first().take(160)) }\n        }\n    }\n}\n"

    /** verbatim copy of app/src/test/java/com/androidharness/app/evolve/GenomeTest.kt. */
    val GENOME_TEST_KT: String = "package com.androidharness.app.evolve\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertNotEquals\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass GenomeTest {\n\n    private fun genome() = Genome(\n        createdAt = 1_000L,\n        label = \"Add grep paging\",\n        hypothesis = \"Paging a grep result keeps long runs inside the context window.\",\n        instructions = listOf(\"Prefer grep with a page limit.\"),\n        skills = mapOf(\"long-grep\" to \"---\\nname: long-grep\\n---\\nUse paging.\"),\n        skillEnable = setOf(\"long-grep\"),\n        hooks = listOf(GenomeHook(\"tool.after\", \"grep\", \"echo done\")),\n        agents = mapOf(\"reviewer\" to GenomeAgent(\"reviewer\", \"Review the diff.\")),\n        proposerNotes = \"Try paging first.\",\n    ).identified()\n\n    @Test\n    fun `hashing is deterministic and the id is 16 hex characters`() {\n        val first = genome()\n        val second = genome()\n        assertEquals(first.id, second.id)\n        assertTrue(first.id.matches(Regex(\"[a-f0-9]{16}\")))\n    }\n\n    @Test\n    fun `map and set order does not change the hash`() {\n        val a = Genome(skills = linkedMapOf(\"b\" to \"2\", \"a\" to \"1\"), skillEnable = linkedSetOf(\"b\", \"a\"))\n        val b = Genome(skills = linkedMapOf(\"a\" to \"1\", \"b\" to \"2\"), skillEnable = linkedSetOf(\"a\", \"b\"))\n        assertEquals(a.computeId(), b.computeId())\n    }\n\n    @Test\n    fun `line endings and surrounding whitespace do not change the hash`() {\n        val a = Genome(instructions = listOf(\"  be careful  \"), skills = mapOf(\"s\" to \"body\\n\"))\n        val b = Genome(instructions = listOf(\"be careful\"), skills = mapOf(\"s\" to \"body\"))\n        assertEquals(a.computeId(), b.computeId())\n    }\n\n    @Test\n    fun `any content edit changes the hash`() {\n        val base = genome()\n        assertNotEquals(base.id, base.copy(instructions = base.instructions + \"One more.\").computeId())\n        assertNotEquals(base.id, base.copy(skills = base.skills + (\"other\" to \"text\")).computeId())\n        assertNotEquals(base.id, base.copy(hooks = emptyList()).computeId())\n        assertNotEquals(base.id, base.copy(agents = emptyMap()).computeId())\n        assertNotEquals(base.id, base.copy(proposerNotes = \"No.\").computeId())\n    }\n\n    @Test\n    fun `lineage and presentation stay out of the payload`() {\n        val base = genome()\n        val relabelled = base.copy(id = \"\", parent = \"ffffffffffffffff\", createdAt = 9_999L, label = \"Other\", hypothesis = \"Other reason\")\n        assertEquals(base.id, relabelled.computeId())\n        assertTrue(base.payload().id.isEmpty())\n    }\n\n    @Test\n    fun `diff names the fields that changed`() {\n        val base = genome()\n        val changed = base.copy(instructions = base.instructions + \"Also check the diff.\")\n        val diff = base.diff(changed)\n        assertTrue(diff.contains(\"instructions\"))\n        assertTrue(diff.contains(\"Also check the diff.\"))\n        assertEquals(\"No content changes.\", base.diff(base))\n    }\n}\n"

    /** app/src/main/java/com/androidharness/app/evolve/BudgetLedger.kt with ONE deliberately broken line (marked BUG). */
    val BUDGET_LEDGER_KT_BROKEN: String = "package com.androidharness.app.evolve\n\nenum class BudgetRole { PROPOSER, WORKER, CRITIC }\n\n/**\n * Shared token/cost/wall budget for one evolution run, enforced by the\n * trusted core, not by the proposer. [consume] checks before it adds, so\n * a budget can never overshoot: a failed consume changes nothing.\n */\nclass BudgetLedger(\n    val maxTokens: Long = 100_000,\n    val maxWallMs: Long = 30L * 60 * 1000,\n    val maxGenerations: Int = 3,\n    val maxCandidates: Int = 4,\n    val stagnationLimit: Int = 2,\n) {\n    private val tokensByRole = mutableMapOf<BudgetRole, Long>()\n    private var wallUsedMs: Long = 0\n    var generationsRun: Int = 0\n        private set\n    var consecutiveStagnant: Int = 0\n        private set\n\n    val tokensUsed: Long get() = tokensByRole.values.sum()\n    val tokensRemaining: Long get() = (maxTokens - tokensUsed).coerceAtLeast(0)\n    val wallRemainingMs: Long get() = (maxWallMs - wallUsedMs).coerceAtLeast(0)\n\n    fun tokensUsedBy(role: BudgetRole): Long = tokensByRole[role] ?: 0L\n\n    @Synchronized\n    fun consume(role: BudgetRole, tokens: Long, wallMs: Long): Boolean {\n        if (tokens < 0 || wallMs < 0) return false\n        if (tokensUsed + tokens > maxTokens) return false\n        if (wallUsedMs + wallMs > maxWallMs) return false\n        tokensByRole[role] = (tokensByRole[role] ?: 0L) + tokens\n        wallUsedMs += wallMs\n        return true\n    }\n\n    @Synchronized\n    fun recordGeneration(improved: Boolean) {\n        generationsRun++\n        // BUG INTRODUCED FOR THIS TASK: improvement must reset the stagnation counter, not grow it.\n        consecutiveStagnant = if (improved) consecutiveStagnant + 1 else 0\n    }\n\n    fun shouldStop(): Boolean =\n        generationsRun >= maxGenerations || consecutiveStagnant >= stagnationLimit || wallUsedMs >= maxWallMs\n\n    fun stopReason(): String? = when {\n        generationsRun >= maxGenerations -> \"generation cap reached (\$maxGenerations)\"\n        consecutiveStagnant >= stagnationLimit -> \"stagnation: \$stagnationLimit generations without improvement\"\n        wallUsedMs >= maxWallMs -> \"wall-clock budget exhausted\"\n        else -> null\n    }\n}\n"

    /** verbatim copy of app/src/test/java/com/androidharness/app/evolve/BudgetLedgerTest.kt. */
    val BUDGET_LEDGER_TEST_KT: String = "package com.androidharness.app.evolve\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertFalse\nimport org.junit.Assert.assertNull\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass BudgetLedgerTest {\n\n    @Test\n    fun `consume refuses an overshoot and changes nothing`() {\n        val ledger = BudgetLedger(maxTokens = 100, maxWallMs = 1_000)\n        assertTrue(ledger.consume(BudgetRole.WORKER, 60, 500))\n        assertFalse(ledger.consume(BudgetRole.WORKER, 41, 0))\n        assertEquals(60L, ledger.tokensUsed)\n        assertFalse(ledger.consume(BudgetRole.WORKER, 0, 501))\n        assertEquals(500L, ledger.maxWallMs - ledger.wallRemainingMs)\n    }\n\n    @Test\n    fun `stagnation stops a run after the limit`() {\n        val ledger = BudgetLedger(maxGenerations = 3, stagnationLimit = 2)\n        assertFalse(ledger.shouldStop())\n        ledger.recordGeneration(false)\n        assertFalse(ledger.shouldStop())\n        ledger.recordGeneration(false)\n        assertTrue(ledger.shouldStop())\n        assertTrue(ledger.stopReason()!!.contains(\"stagnation\"))\n    }\n\n    @Test\n    fun `improvement resets the stagnation counter`() {\n        val ledger = BudgetLedger(maxGenerations = 3, stagnationLimit = 2)\n        ledger.recordGeneration(false)\n        ledger.recordGeneration(true)\n        assertEquals(0, ledger.consecutiveStagnant)\n        assertFalse(ledger.shouldStop())\n    }\n\n    @Test\n    fun `generation cap stops a run`() {\n        val ledger = BudgetLedger(maxGenerations = 2, stagnationLimit = 5)\n        ledger.recordGeneration(true)\n        ledger.recordGeneration(true)\n        assertTrue(ledger.shouldStop())\n        assertEquals(\"generation cap reached (2)\", ledger.stopReason())\n    }\n\n    @Test\n    fun `negative consume is refused`() {\n        val ledger = BudgetLedger()\n        assertFalse(ledger.consume(BudgetRole.PROPOSER, -1, 0))\n        assertFalse(ledger.consume(BudgetRole.PROPOSER, 0, -1))\n        assertEquals(0L, ledger.tokensUsed)\n        assertNull(ledger.stopReason())\n    }\n}\n"

    /** app/src/main/java/com/androidharness/app/evolve/TraceMiner.kt with ONE deliberately broken line (marked BUG). */
    val TRACE_MINER_KT_BROKEN: String = "package com.androidharness.app.evolve\n\nimport com.androidharness.app.tools.SecretRedactor\n\n/**\n * Mines redacted failure patterns from run history. Everything is run\n * through [SecretRedactor] before it is stored or returned, and only\n * counted phrases come out: never raw traces, never secrets.\n */\nobject TraceMiner {\n    data class PatternCount(val pattern: String, val count: Int)\n    data class Diagnosis(val topPatterns: List<PatternCount>, val suggestedHints: List<String>)\n\n    private val failureWords = listOf(\"fail\", \"error\", \"timeout\", \"refused\", \"stuck\", \"missing\", \"lost\", \"wrong\", \"crash\")\n\n    fun mine(histories: List<String>): Diagnosis {\n        val counts = linkedMapOf<String, Int>()\n        histories.forEach { raw ->\n            SecretRedactor.redact(raw).lines().forEach { line ->\n                val clean = line.trim().lowercase()\n                if (clean.isBlank()) return@forEach\n                if (failureWords.none { it in clean }) return@forEach\n                // BUG INTRODUCED FOR THIS TASK: numbers must be folded to '#', not deleted.\n                val pattern = clean.replace(Regex(\"[0-9]+\"), \"\").replace(Regex(\"\\\\s+\"), \" \").take(120)\n                counts[pattern] = (counts[pattern] ?: 0) + 1\n            }\n        }\n        val top = counts.entries.sortedByDescending { it.value }.take(5)\n            .map { PatternCount(it.key, it.value) }\n        val hints = mutableListOf<String>()\n        val joined = top.joinToString(\" \") { it.pattern }\n        if (\"timeout\" in joined) hints += \"tighten hook timeouts and add a retry note\"\n        if (\"verify\" in joined || \"fail\" in joined) hints += \"add a verify-before-done instruction\"\n        if (\"pinned\" in joined || \"lost\" in joined) hints += \"add a pinned-constraint instruction\"\n        if (\"patch\" in joined || \"hunk\" in joined) hints += \"add a stale-hunk recovery instruction\"\n        if (\"stuck\" in joined) hints += \"add a stop-and-ask instruction instead of looping\"\n        if (hints.isEmpty() && top.isNotEmpty()) hints += \"add one clarifying instruction for the top failure\"\n        return Diagnosis(top, hints.map { SecretRedactor.redact(it) })\n    }\n}\n"

    /** verbatim copy of app/src/main/java/com/androidharness/app/tools/SecretRedactor.kt. */
    val SECRET_REDACTOR_KT: String = "package com.androidharness.app.tools\n\n/**\n * Scrub common secret shapes from tool output before it hits the model, the\n * chat DB, or the screen.\n *\n * Two rules of the road:\n *  - Match on a vendor prefix or a credential-ish name, never on entropy. A\n *    \"long random-looking string\" rule would also swallow commit SHAs, hashes\n *    and base64 blobs, and the agent has to feed those back into later\n *    commands.\n *  - Nothing here may backtrack super-linearly. Tool output runs to 100k chars\n *    and this sits on every result, so the name/value split is a linear regex\n *    plus a plain-code predicate instead of one clever pattern.\n */\nobject SecretRedactor {\n\n    /** A regex plus what to leave behind when it fires. */\n    private class Rule(val regex: Regex, val replacement: String)\n\n    private val PREFIX_RULES = listOf(\n        // PEM key blocks (RSA / EC / OPENSSH / PGP).\n        Rule(\n            Regex(\"\"\"-----BEGIN [A-Z ]*PRIVATE KEY-----[\\s\\S]*?-----END [A-Z ]*PRIVATE KEY-----\"\"\"),\n            \"[redacted]\",\n        ),\n\n        // OpenAI: the legacy sk-<48 alnum> shape, then the hyphenated project,\n        // service-account, admin and org keys, plus OpenRouter's sk-or-v1-<64>.\n        // The hyphen is what made the old single sk- rule miss all of these.\n        Rule(Regex(\"\"\"\\bsk-[A-Za-z0-9]{10,}\"\"\"), \"[redacted]\"),\n        Rule(Regex(\"\"\"\\bsk-(?:proj|svcacct|admin|org|or-v1)-[A-Za-z0-9_\\-]{12,}\"\"\"), \"[redacted]\"),\n        // Anthropic: sk-ant-api03-<95>, sk-ant-admin01-<...>\n        Rule(Regex(\"\"\"\\bsk-ant-[A-Za-z0-9_\\-]{12,}\"\"\"), \"[redacted]\"),\n\n        // Vendors that put a distinctive marker up front.\n        Rule(Regex(\"\"\"\\bgsk_[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),        // Groq\n        Rule(Regex(\"\"\"\\bxai-[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),        // xAI\n        Rule(Regex(\"\"\"\\bpplx-[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),       // Perplexity\n        Rule(Regex(\"\"\"\\bfw_[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),         // Fireworks\n        Rule(Regex(\"\"\"\\br8_[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),         // Replicate\n        Rule(Regex(\"\"\"\\bhf_[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),         // Hugging Face\n        Rule(Regex(\"\"\"\\btgp_v1_[A-Za-z0-9_\\-]{12,}\"\"\"), \"[redacted]\"),  // Together\n        Rule(Regex(\"\"\"\\btvly-[A-Za-z0-9_\\-]{12,}\"\"\"), \"[redacted]\"),    // Tavily\n        Rule(Regex(\"\"\"\\bfc-[A-Za-z0-9]{24,}\"\"\"), \"[redacted]\"),         // Firecrawl\n        Rule(Regex(\"\"\"\\bjina_[A-Za-z0-9_\\-]{24,}\"\"\"), \"[redacted]\"),    // Jina\n\n        // Cloud and infra.\n        Rule(Regex(\"\"\"\\b(?:AKIA|ASIA)[0-9A-Z]{16}\\b\"\"\"), \"[redacted]\"),  // AWS access key id\n        Rule(Regex(\"\"\"\\bAIza[0-9A-Za-z\\-_]{20,}\"\"\"), \"[redacted]\"),      // Google API key\n        Rule(Regex(\"\"\"\\bya29\\.[A-Za-z0-9_\\-]{20,}\"\"\"), \"[redacted]\"),    // Google OAuth\n        Rule(Regex(\"\"\"\\bdop_v1_[0-9a-f]{64}\"\"\"), \"[redacted]\"),          // DigitalOcean\n        Rule(Regex(\"\"\"\\bsbp_[A-Za-z0-9]{24,}\"\"\"), \"[redacted]\"),         // Supabase PAT\n        Rule(Regex(\"\"\"\\bsb_(?:publishable|secret)_[A-Za-z0-9_\\-]{12,}\"\"\"), \"[redacted]\"),\n\n        // Code hosts and package registries.\n        Rule(Regex(\"\"\"\\bgh[posru]_[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),    // GitHub PAT / OAuth / app\n        Rule(Regex(\"\"\"github_pat_[A-Za-z0-9_]{20,}\"\"\"), \"[redacted]\"),    // GitHub fine-grained\n        Rule(Regex(\"\"\"\\bglpat-[A-Za-z0-9_\\-]{16,}\"\"\"), \"[redacted]\"),     // GitLab\n        Rule(Regex(\"\"\"\\bnpm_[A-Za-z0-9]{32,}\"\"\"), \"[redacted]\"),          // npm\n        Rule(Regex(\"\"\"\\bdckr_pat_[A-Za-z0-9_\\-]{16,}\"\"\"), \"[redacted]\"),  // Docker Hub\n        Rule(Regex(\"\"\"\\bnapi-[A-Za-z0-9]{32,}\"\"\"), \"[redacted]\"),         // Notion\n        Rule(Regex(\"\"\"\\blin_api_[A-Za-z0-9]{24,}\"\"\"), \"[redacted]\"),      // Linear\n\n        // Payments and messaging.\n        Rule(Regex(\"\"\"\\b[sr]k_(?:live|test)_[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),          // Stripe\n        Rule(Regex(\"\"\"\\bwhsec_[A-Za-z0-9]{16,}\"\"\"), \"[redacted]\"),                        // Stripe webhook\n        Rule(Regex(\"\"\"\\bSG\\.[A-Za-z0-9_\\-]{16,}\\.[A-Za-z0-9_\\-]{16,}\"\"\"), \"[redacted]\"),  // SendGrid\n        Rule(Regex(\"\"\"\\b(?:AC|SK)[0-9a-fA-F]{32}\\b\"\"\"), \"[redacted]\"),                    // Twilio SID\n        Rule(Regex(\"\"\"\\bxox[abpros]-[A-Za-z0-9\\-]{10,}\"\"\"), \"[redacted]\"),                // Slack\n        Rule(Regex(\"\"\"\\b\\d{8,10}:[A-Za-z0-9_\\-]{33,}\"\"\"), \"[redacted]\"),                  // Telegram bot\n\n        // Tokens that carry their own signature.\n        Rule(Regex(\"\"\"\\beyJ[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]*\"\"\"), \"[redacted]\"),\n        Rule(Regex(\"\"\"(?i)\\bBearer\\s+\\S+\"\"\"), \"[redacted]\"),\n        Rule(Regex(\"\"\"(?i)\\bBasic\\s+[A-Za-z0-9+/=]{16,}\"\"\"), \"[redacted]\"),\n\n        // user:password@ userinfo in any URL scheme; the scheme and host stay\n        // readable so the model can still tell what it was pointed at.\n        Rule(\n            Regex(\"\"\"([a-zA-Z][A-Za-z0-9+.\\-]{1,20}://)[^\\s/@:]{1,64}:[^\\s/@]{6,}@\"\"\"),\n            \"\$1[redacted]@\",\n        ),\n    )\n\n    /**\n     * `NAME = value` / `NAME: value`, the value taken as one unbroken token.\n     * Deliberately blind to what NAME means, that call is made in code below.\n     */\n    private val ASSIGNMENT = Regex(\n        \"(?m)(?<![A-Za-z0-9])([A-Za-z0-9_.\\\\-]{1,64})\" +\n            \"([\\\"']?[^\\\\S\\\\r\\\\n]{0,8}[=:][^\\\\S\\\\r\\\\n]{0,8}[\\\"']?)\" +\n            \"([A-Za-z0-9+/_\\\\-]{16,})(?![A-Za-z0-9_(])\",\n    )\n\n    /** Same shape, but passwords carry no prefix so the value may be short. */\n    private val PASSWORD = Regex(\n        \"(?m)(?<![A-Za-z0-9])([A-Za-z0-9_.\\\\-]{1,64})\" +\n            \"([\\\"']?[^\\\\S\\\\r\\\\n]{0,8}[=:][^\\\\S\\\\r\\\\n]{0,8}[\\\"']?)\" +\n            \"([^\\\\s\\\"']{3,})\",\n    )\n\n    /**\n     * Words that make an identifier a credential holder. Matched per `_`/`-`/`.`\n     * segment, so `ANTHROPIC_API_KEY`, `AWS_SECRET_ACCESS_KEY` and\n     * `SECRET_KEY_BASE` all qualify while `monkey`, `keyboard` and `tokenizer`\n     * do not.\n     */\n    private val CREDENTIAL_WORDS = setOf(\n        \"key\", \"keys\", \"apikey\", \"secret\", \"secrets\", \"secretkey\",\n        \"token\", \"tokens\", \"accesstoken\", \"credential\", \"credentials\",\n        \"password\", \"passwd\", \"passphrase\", \"passcode\",\n        \"authkey\", \"accesskey\", \"privatekey\", \"signingkey\", \"sessionkey\",\n    )\n\n    /** `pwd` is excluded on purpose: PWD= in env output is a directory. */\n    private val PASSWORD_WORDS = setOf(\"password\", \"passwd\", \"passphrase\", \"passcode\")\n\n    private fun segments(name: String) = name.lowercase().split('_', '-', '.')\n\n    fun redact(text: String): String {\n        var out = text\n        for (rule in PREFIX_RULES) {\n            out = rule.regex.replace(out, rule.replacement)\n        }\n        out = ASSIGNMENT.replace(out) { m ->\n            val name = m.groupValues[1]\n            if (segments(name).any { it in CREDENTIAL_WORDS }) {\n                name + m.groupValues[2] + \"[redacted]\"\n            } else {\n                m.value\n            }\n        }\n        out = PASSWORD.replace(out) { m ->\n            val name = m.groupValues[1]\n            if (segments(name).any { it in PASSWORD_WORDS }) {\n                name + m.groupValues[2] + \"[redacted]\"\n            } else {\n                m.value\n            }\n        }\n        return out\n    }\n}"

    /** verbatim copy of app/src/test/java/com/androidharness/app/evolve/TraceMinerTest.kt. */
    val TRACE_MINER_TEST_KT: String = "package com.androidharness.app.evolve\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass TraceMinerTest {\n\n    @Test\n    fun `counts repeated failure lines and suggests a hint`() {\n        val diagnosis = TraceMiner.mine(\n            listOf(\n                \"apply_patch failed: hunk is stale\\napply_patch failed: hunk is stale\\n\",\n                \"timeout after 30s waiting for the tool\\n\",\n                \"all good here\\n\",\n            ),\n        )\n        assertEquals(2, diagnosis.topPatterns.first { \"stale\" in it.pattern }.count)\n        assertTrue(diagnosis.suggestedHints.any { \"hunk\" in it })\n    }\n\n    @Test\n    fun `redacts secrets before they leave the miner`() {\n        val diagnosis = TraceMiner.mine(listOf(\"error: api_key = ghp_abcdefghij1234567890abcdefghij12 failed\\n\"))\n        assertTrue(diagnosis.topPatterns.none { \"ghp_\" in it.pattern })\n        assertTrue(diagnosis.topPatterns.none { \"abcdefghij\" in it.pattern })\n    }\n\n    @Test\n    fun `empty history gives an empty diagnosis`() {\n        val diagnosis = TraceMiner.mine(emptyList())\n        assertTrue(diagnosis.topPatterns.isEmpty())\n        assertTrue(diagnosis.suggestedHints.isEmpty())\n    }\n\n    @Test\n    fun `numbers are folded so the same failure counts once per shape`() {\n        val diagnosis = TraceMiner.mine(listOf(\"error on line 42 failed\\nerror on line 99 failed\\n\"))\n        assertEquals(1, diagnosis.topPatterns.size)\n        assertEquals(2, diagnosis.topPatterns.single().count)\n        assertTrue(\"#\" in diagnosis.topPatterns.single().pattern)\n    }\n}\n"

